// Actual pinned middleware and Go Request.BasicAuth, no parser reimplementation.
package main
import("encoding/json";"os";"net/http";"net/http/httptest";"github.com/livekit/livekit-server/pkg/service")
func main(){var rows []struct{ID string `json:"id"`;Authorization *string `json:"authorization"`;HeaderValues []string `json:"header_values"`;Username string `json:"username"`;Password string `json:"password"`};f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};defer f.Close();if e=json.NewDecoder(f).Decode(&rows);e!=nil{panic(e)};if len(rows)!=21{panic("expected all 21 source cases")};seen:=map[string]bool{};for _,row:=range rows{if row.ID==""||seen[row.ID]{panic("empty or duplicate source case ID")};seen[row.ID]=true};out:=json.NewEncoder(os.Stdout);for _,row:=range rows{request:=httptest.NewRequest("GET","http://owned.invalid/metrics",nil);if len(row.HeaderValues)>0{for _,value:=range row.HeaderValues{request.Header.Add("Authorization",value)}}else if row.Authorization!=nil{request.Header.Set("Authorization",*row.Authorization)};w:=httptest.NewRecorder();called:=false;service.GenBasicAuthMiddleware(row.Username,row.Password)(w,request,func(rw http.ResponseWriter,_ *http.Request){called=true;rw.WriteHeader(200)});response:=w.Result();if e=out.Encode(map[string]any{"id":row.ID,"status":response.StatusCode,"www_authenticate":response.Header.Get("WWW-Authenticate"),"content_type":response.Header.Get("Content-Type"),"body_length":w.Body.Len(),"downstream_called":called});e!=nil{panic(e)}}}
